package com.eventpulse.util;
import com.amazonaws.services.lambda.runtime.events.APIGatewayV2HTTPResponse; import com.eventpulse.dto.ApiResponse; import com.fasterxml.jackson.databind.ObjectMapper; import java.util.Map;
public final class ResponseUtil { public static final ObjectMapper JSON=new ObjectMapper().findAndRegisterModules(); private ResponseUtil(){} public static APIGatewayV2HTTPResponse response(int status,Object body){try{return APIGatewayV2HTTPResponse.builder().withStatusCode(status).withHeaders(Map.of("content-type","application/json","access-control-allow-origin","*","access-control-allow-headers","content-type,authorization","access-control-allow-methods","GET,POST,PUT,DELETE,OPTIONS")).withBody(JSON.writeValueAsString(body)).build();}catch(Exception e){return APIGatewayV2HTTPResponse.builder().withStatusCode(500).withBody("{\"success\":false,\"error\":{\"code\":\"INTERNAL_ERROR\",\"message\":\"Internal server error\"}}").build();}} public static APIGatewayV2HTTPResponse error(int status,String code,String message){return response(status,ApiResponse.failure(code,message));} }
